// The Twin platform's backups (apps/platform/src/backup.ts at 96ca447): one JSON archive of the state directory put
// into a bucket through the unchanged @aws-sdk/client-s3, path-style through AWS_ENDPOINT_URL, the bucket made when
// missing; the kept archives listed and one restored.
import assert from 'node:assert/strict';
import { CreateBucketCommand, GetObjectCommand, HeadBucketCommand, ListObjectsV2Command, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const bucket = 'volter-platform-backups';
const prefix = 'platform-state/';
const s3 = new S3Client({ region: process.env.AWS_REGION || 'us-east-1', ...(process.env.AWS_ENDPOINT_URL ? { endpoint: process.env.AWS_ENDPOINT_URL, forcePathStyle: true } : {}) });
const ensureBucket = async () => { try { await s3.send(new HeadBucketCommand({ Bucket: bucket })); } catch { await s3.send(new CreateBucketCommand({ Bucket: bucket })); } };
const list = async () => { await ensureBucket(); const r = await s3.send(new ListObjectsV2Command({ Bucket: bucket, Prefix: prefix })); return (r.Contents ?? []).map((o) => o.Key).filter(Boolean).sort(); };
const restore = async (key) => JSON.parse(await (await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }))).Body.transformToString());
const files = { 'orgs/orbit-apps.json': Buffer.from(JSON.stringify({ id: 'orbit-apps', name: 'Orbit Apps', members: 3 })).toString('base64'), 'audit/2026-10.log': Buffer.from('org.create orbit-apps\n').toString('base64') };

if (process.argv[2] === 'readback') {
  const keys = await list();
  assert.equal(keys.length, 1, JSON.stringify(keys));
  const archive = await restore(keys[0]);
  assert.deepEqual(archive.files, files);
  console.log(JSON.stringify({ retained: true, key: keys[0], files: Object.keys(archive.files).length, madeAt: archive.madeAt }));
} else {
  assert.deepEqual(await list(), []);
  const archive = { madeAt: new Date().toISOString(), files };
  const body = JSON.stringify(archive);
  const key = `${prefix}${archive.madeAt.replace(/[:.]/g, '-')}.json`;
  await ensureBucket();
  const put = await s3.send(new PutObjectCommand({ Bucket: bucket, Key: key, Body: body, ContentType: 'application/json' }));
  assert.ok(put.ETag);
  assert.deepEqual(await list(), [key]);
  const restored = await restore(key);
  assert.equal(restored.madeAt, archive.madeAt);
  assert.deepEqual(restored.files, files);
  console.log(JSON.stringify({ key, files: Object.keys(files).length, bytes: body.length, etag: put.ETag }));
}
